
(function(root){'use strict';let frames=null;const def=root.NeonNova128Data,previous=root.PolishedSprites.draw;
const ready=new Promise(resolve=>{const im=new Image();im.onload=()=>{frames=def.frames.map(f=>{const[x,y,w,h]=f.rect,c=document.createElement('canvas');c.width=w;c.height=h;const p=c.getContext('2d',{willReadFrequently:true});p.drawImage(im,x,y,w,h,0,0,w,h);const data=p.getImageData(0,0,w,h),v=data.data,mask=new Uint8Array(w*h),queue=new Int32Array(w*h);let head=0,tail=0;const seed=(f.seed[1]-y)*w+f.seed[0]-x;queue[tail++]=seed;mask[seed]=1;while(head<tail){const i=queue[head++],xx=i%w;for(const j of[xx?i-1:-1,xx<w-1?i+1:-1,i>=w?i-w:-1,i+w<w*h?i+w:-1])if(j>=0&&!mask[j]&&v[j*4+3]>60){mask[j]=1;queue[tail++]=j;}}for(let i=0;i<mask.length;i++)if(!mask[i])v[i*4+3]=0;p.putImageData(data,0,0);return{image:c,x:x-f.anchor[0],y:y-f.anchor[1],w,h};});resolve(true);};im.onerror=()=>resolve(false);im.src=def.src;});
root.PolishedSprites.draw=function(c,f,time,scale){if(f.type==='nova'&&f.explodingPose128){if(!frames)return true;if(f.explodingPose128.index===0){c.save();c.translate(0,(f.grappleZ||0)/(scale||1));const r=previous(c,{...f,act:null,explodingPose128:null},time,scale);c.restore();return r;}const p=frames[f.explodingPose128.index],k=def.scale;c.imageSmoothingEnabled=true;c.drawImage(p.image,p.x*k,p.y*k,p.w*k,p.h*k);return true;}const a=f.explodingLock128;if(a&&!a.impacted128&&!a.cleaned128){if(a.t*60>=23&&a.t*60<41)return previous(c,f,time,scale);return previous(c,{...f,heldBy:null,act:null,walk:0,stun:0,down:0,downAge:0,flight:null,grappleZ:0},time,scale);}return previous(c,f,time,scale);};
root.PolishedSprites.ready=Promise.all([root.PolishedSprites.ready,ready]);
function effects(c,g,reduced=false,foreground=false){for(const e of g.effects){if(!foreground&&e.kind==='novaPressure128'){const u=1-e.life/e.total,r=(24+(e.radius-24)*u);c.save();c.globalAlpha=(1-u)*e.strength*(reduced?.45:1);c.strokeStyle='#c6d9e3';c.lineWidth=e.strength>.5?2:1;c.beginPath();c.ellipse(e.x-g.camera,e.y+2,r,r*.18,0,0,Math.PI*2);c.stroke();c.restore();}else if(foreground&&e.kind==='novaCamera128'){const u=e.life/e.total,r=reduced?3:5;c.save();c.globalAlpha=u*(reduced?.2:.65);c.strokeStyle='#fff4d8';c.lineWidth=1.5;c.beginPath();c.moveTo(e.x-g.camera-r,e.y);c.lineTo(e.x-g.camera+r,e.y);c.moveTo(e.x-g.camera,e.y-r);c.lineTo(e.x-g.camera,e.y+r);c.stroke();c.fillStyle='#ffffff';c.fillRect(e.x-g.camera-1.5,e.y-1.5,3,3);c.restore();}}}
root.NeonNovaView128={ready,effects,frames:()=>frames};
})(window);
